// Read-only: pulls the Class XI V1 scenario banks out of the legacy index.html into typed JSON.
// It never writes to index.html. Run: node tools/extract-legacy-banks.mjs  (writes packages/curriculum/src/banks/legacy-v1.ts — generated, do not edit by hand)
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { createHash } from 'node:crypto';
const ROOT = new URL('..', import.meta.url).pathname, SRC = ROOT + 'index.html';
const html = readFileSync(SRC, 'utf8');
/** Return the source text of `const NAME = [ ... ];` by bracket matching (strings and comments respected). */
function literal(name) {
  const start = html.indexOf(`const ${name} = [`); if (start < 0) throw new Error(`array ${name} not found`);
  const i = html.indexOf('[', start); let depth = 0, q = null;
  for (let j = i; j < html.length; j++) {
    const c = html[j], p = html[j - 1];
    if (q) { if (c === q && p !== '\\') q = null; continue; }
    if (c === '"' || c === "'" || c === '`') { q = c; continue; }
    if (c === '/' && html[j + 1] === '/') { j = html.indexOf('\n', j); continue; }
    if (c === '[') depth++; else if (c === ']' && --depth === 0) return { text: html.slice(i, j + 1), line: html.slice(0, start).split('\n').length };
  }
  throw new Error(`unterminated ${name}`);
}
const evalLiteral = (name, ...env) => { const l = literal(name); return { value: new Function(...env.map(e => e[0]), `return ${l.text};`)(...env.map(e => e[1])), line: l.line }; };

// m1 templates mutate M1_ACCTS; run each against a recording proxy (twice, to prove the effect is linear in the amount).
const rec = () => { const d = {}; return { d, p: new Proxy(d, { get: (t, k) => t[k] ?? 0, set: (t, k, v) => { t[k] = v; return true; } }) }; };
const tplSrc = evalLiteral('TPL', ['M1_ACCTS', new Proxy({}, { get: (_t, k) => (k === Symbol.toPrimitive ? undefined : 0) })]);
const m1 = tplSrc.value.map(t => {
  const run = (n, cost) => { const r = rec(); new Function('M1_ACCTS', 'n', 'cost', `return (${t.fn.toString()})(n, cost)`)(r.p, n, cost); return r.d; };
  const keys = (...ds) => [...new Set(ds.flatMap(d => Object.keys(d)))];
  const sale = run(1000, 0), sale2 = run(2000, 0);
  if (!t.needsCost) return { id: t.id, label: t.label, desc: t.desc, effectPer1000: sale, linear: keys(sale, sale2).every(k => (sale2[k] ?? 0) === 2 * (sale[k] ?? 0)) };
  // sale templates take (sale value, cost of goods): record both coefficients and prove f(s, c) = s·A + c·B
  const cost = Object.fromEntries(Object.entries(run(0, 1000))), both = run(1000, 1000);
  const linear = keys(sale, cost, both).every(k => (both[k] ?? 0) === (sale[k] ?? 0) + (cost[k] ?? 0)) && keys(sale, sale2).every(k => (sale2[k] ?? 0) === 2 * (sale[k] ?? 0));
  return { id: t.id, label: t.label, desc: t.desc, effectPer1000: sale, costEffectPer1000: cost, linear };
});
const m2 = evalLiteral('M2_SCENES').value.map(s => ({ text: s.text, amount: s.amt, pool: s.pool.map(p => ({ account: p[0], type: p[1] })), debit: s.right.debit, credit: s.right.credit, delta: s.delta, why: s.why }));
const m4 = evalLiteral('JB').value.map(s => ({ text: s.scene, pool: s.pool, debit: s.answer.debit, credit: s.answer.credit, amount: s.answer.amt, why: s.why }));
const m5 = evalLiteral('GAME').value.map(g => ({ question: g.q, options: g.o, answer: g.a, why: g.why }));
const tbPool = evalLiteral('TB_POOL').value.map(x => ({ account: x.n, side: x.s }));
const tbItems = evalLiteral('TB_ITEMS').value.map(x => ({ account: x.n, side: x.s }));
const bal = evalLiteral('BAL').value.map(x => ({ account: x.n, type: x.ty, side: x.side, why: x.why.replace(/<[^>]+>/g, '') }));
const out = {
  source: { file: 'index.html', sha256: createHash('sha256').update(html).digest('hex'), extractedBy: 'tools/extract-legacy-banks.mjs',
    arrays: { TPL: tplSrc.line, M2_SCENES: literal('M2_SCENES').line, JB: literal('JB').line, GAME: literal('GAME').line, TB_POOL: literal('TB_POOL').line, TB_ITEMS: literal('TB_ITEMS').line, BAL: literal('BAL').line } },
  m1, m2, m4, m5, tbPool, tbItems, bal,
};
mkdirSync(ROOT + 'packages/curriculum/src/banks', { recursive: true });
writeFileSync(ROOT + 'packages/curriculum/src/banks/legacy-v1.ts', `// GENERATED by tools/extract-legacy-banks.mjs from the legacy index.html — do not edit. Re-run the script if index.html changes.\nimport type { LegacyV1 } from './legacy-types';\nexport const LEGACY_V1: LegacyV1 = ${JSON.stringify(out, null, 1)};\n`);
console.log(`m1 ${m1.length} (non-linear ${m1.filter(x => !x.linear).length}) · m2 ${m2.length} · m4 ${m4.length} · m5 ${m5.length} · TB_POOL ${tbPool.length} · TB_ITEMS ${tbItems.length} · BAL ${bal.length}`);
